//     expression token by token under the parser. When the parser accepts a
//     complete expression, CloseConstrainedSpan emits ">>" and returns to Phase 0.
// This supports an arbitrary number of << >> spans across the step-by-step
// reasoning chain and the final answer span. The parser enforces that only
// valid symbolic expressions (numbers, problem variables, and operations
// +, -, /, //, %, (), int()) appear inside spans.
// We use AdaptiveConstrainedStep with caller-supplied validTokenGroups so that
// variable-name tokens from the problem are soft-boosted when the parser state
// is narrow, improving grounding.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity (insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)):
//   Free branch: insideConstrainedOut is false, so the implication is vacuous
//     unless we observe "<<" via RenderedEndsWith. In that case we set
//     currentConstrainedOut := [], which satisfies IsValidPrefix([]) by
//     the method precondition parser.IsValidPrefix([]).
//   Complete branch: CloseConstrainedSpan sets insideConstrainedOut := false,
//     making the implication vacuously true, and sets currentConstrainedOut := [].
//   Constrained branch: AdaptiveConstrainedStep returns either eosToken (loop
//     breaks, no state change) or a parser-valid next token by its postcondition.
//     AppendConstrainedToken extends currentConstrainedOut by exactly that token,
//     and its postcondition guarantees the resulting currentConstrainedOut is
//     still parser.IsValidPrefix, preserving the invariant.
//
// progress (|generated| <= |generatedPrefix| + steps):
//   Free branch: UnconstrainedStep costs exactly 1 step; we append at most one
//     token to generated. Whether or not we enter constrained mode, the bound
//     holds: |generated| increases by at most 1 while steps increases by 1.
//   Complete branch: CloseConstrainedSpan costs 1 step and appends ">>" (one
//     token) to generated, so both sides grow by 1, preserving the bound.
//   Constrained branch: AdaptiveConstrainedStep costs exactly 1 step. On
//     eosToken the loop breaks without appending; on a valid token
//     AppendConstrainedToken appends exactly one token. Either way
//     |generated| increases by at most 1 while steps increases by 1.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance := "Solve the math word problem step by step. Wrap each intermediate symbolic expression in << >> delimiters and wrap the final symbolic answer in << >>. Use only numbers, the variables defined in the question, and the operations +, -, /, //, %, (), int(). Respond in the format: Lets think step by step. <reasoning> The final answer is <<symbolic expression>>.";
helpers.AppendTaskGuidance(lm, guidance);

var steps: nat := 0;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      generated := generated + [next];
      if RenderedEndsWith(generated, "<<") {
        insideConstrainedOut := true;
        currentConstrainedOut := [];
      }
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := closedGenerated;
    insideConstrainedOut := closedInside;
    currentConstrainedOut := closedCurrent;
    steps := steps + 1;
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.AdaptiveConstrainedStep(
      lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 4.0, 12, eosToken
    );
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := appendedGenerated;
      insideConstrainedOut := appendedInside;
      currentConstrainedOut := appendedCurrent;
    }
  }
}

cost := steps;

